// Parsea la respuesta de Claude y la combina con los datos del prospecto
const claudeRaw = $json;
const prospecto = $('03 · Lista de Prospectos').item.json;

// Extraer el texto de la respuesta de Claude
const text = claudeRaw.content[0].text.trim();

// Parsear JSON con manejo de errores (Claude puede añadir texto extra)
let emailData;
try {
  const match = text.match(/\{[\s\S]*\}/);
  emailData = JSON.parse(match[0]);
} catch(e) {
  emailData = {
    asunto: 'Email para ' + prospecto.nombre,
    cuerpo: 'Error al generar email. Verifica la API key de Claude.',
    angulo_usado: 'Error de parsing'
  };
}

// Calcular puntuación de oportunidad (1-10)
let score = 5;
if (!prospecto.tiene_pixel_meta && !prospecto.gasta_en_ads) {
  score = 9; // Sin infraestructura = máxima oportunidad
} else if (prospecto.tiene_pixel_meta && !prospecto.gasta_en_ads) {
  score = 7; // Tiene pixel pero no invierte = oportunidad alta
} else if (prospecto.gasta_en_ads && prospecto.ads_estimado && prospecto.ads_estimado.includes('500')) {
  score = 6; // Ads bajo presupuesto = potencial de escala
} else if (prospecto.gasta_en_ads) {
  score = 4; // Ya invierte bien = menor urgencia
}
// Bonus por volumen de audiencia
if (prospecto.instagram_followers > 25000) score = Math.min(10, score + 1);
else if (prospecto.instagram_followers > 10000) score = Math.min(10, score + 0.5);
score = Math.round(score);

// Badge de estado de inversión en ads
let badge_estado, badge_color;
if (!prospecto.gasta_en_ads) {
  badge_estado = 'Sin ads';
  badge_color = 'red';
} else if (prospecto.ads_estimado && (prospecto.ads_estimado.includes('500') || prospecto.ads_estimado.includes('menos'))) {
  badge_estado = 'Ads bajo presupuesto';
  badge_color = 'orange';
} else {
  badge_estado = 'Con ads activos';
  badge_color = 'green';
}

// Color indicador de actividad en Instagram
let actividad_ig_color;
const ultima = prospecto.ultima_publicacion_ig;
if (ultima === 'hoy' || ultima === 'ayer') {
  actividad_ig_color = 'green';
} else if (ultima.includes('días')) {
  actividad_ig_color = 'yellow';
} else {
  actividad_ig_color = 'red';
}

return [{
  json: {
    ...prospecto,
    asunto: emailData.asunto,
    cuerpo: emailData.cuerpo,
    angulo_usado: emailData.angulo_usado,
    oportunidad_score: score,
    badge_estado,
    badge_color,
    actividad_ig_color
  }
}];
